        ["Ajustes no período", summary.data.adjustments], ["Divergências abertas", summary.data.open_differences],
      ].map(([label,value])=><div className="rounded-lg border p-3" key={label}><p className="text-sm text-muted-foreground">{label}</p><p className="text-xl font-semibold">{formatQuantity(Number(value))}</p></div>)}</div>
      <p className="text-xs text-muted-foreground">Entradas e saídas incluem transferências físicas. Saldo On Hand atual; reservas e valor financeiro não são calculados.</p>
      <div className="flex flex-wrap gap-3">{summary.data.locations.map(l=><span key={l.id} className="rounded border px-3 py-2 text-sm">{l.name}: <strong>{formatQuantity(l.on_hand)}</strong></span>)}</div>
    </> : null}
